<script setup>
import { computed, ref, watch } from 'vue';
import { componentInfo } from '../workflow/catalog.js';
import { isOpaque, nodeName } from '../workflow/graph.js';
import VirtualList from '../ui/VirtualList.vue';
import { Button, Icon, Notice } from '../ui/index.js';
import { lazyNode } from '../workflow/lazy-nodes.js';
import CodePreview from './CodePreview.vue';
const props = defineProps({ graph: { type: Object, required: true }, loadNode: Function, contextKey: String });
const selected = ref(null), collapsed = ref(new Set()), rawOpen = ref(false);
const loading = ref(false), error = ref(null);
let ticket = 0;
async function choose(id) {
 selected.value = id; error.value = null;
 const generation = ++ticket, node = props.graph.nodes.find(node => node.id === id);
 loading.value = false;
 if (!lazyNode(node)) return;
 loading.value = true;
 try { if (!props.loadNode) throw new Error('节点读取不可用，请重新载入'); await props.loadNode(id); }
 catch (problem) { if (generation === ticket) error.value = problem; }
 finally { if (generation === ticket) loading.value = false; }
}
const rows = computed(() => {
 const result=[],visited=new Set(),nodes=new Map(props.graph.nodes.map(n=>[n.id,n])),children=new Map();
 for(const e of props.graph.edges){if(!children.has(e.sourceNodeId))children.set(e.sourceNodeId,[]);children.get(e.sourceNodeId).push(e);}
 for(const edges of children.values())edges.sort((a,b)=>a.properties.order-b.properties.order);
 const root=props.graph.nodes.find(n=>n.properties.component==='TestPlan');const stack=root?[[root,0]]:[];
 while(stack.length){const [node,depth]=stack.pop();if(visited.has(node.id))continue;visited.add(node.id);const nested=isOpaque(node)?[]:children.get(node.id)||[];result.push({node,depth,hasChildren:nested.length>0});if(!collapsed.value.has(node.id))for(let i=nested.length-1;i>=0;i--){const child=nodes.get(nested[i].targetNodeId);if(child)stack.push([child,depth+1]);}}
 return result;
});
const node = computed(() => props.graph.nodes.find(node => node.id === selected.value) || (props.graph.nodes.some(lazyNode) ? null : props.graph.nodes[0]));
const info = computed(() => componentInfo(node.value?.properties.component));
const parameters = computed(() => Object.entries(node.value?.properties.config || {}).map(([key, value]) => ({ key, label: info.value.fields.find(field => field.key === key)?.label || '扩展参数', value })));
function toggle(id) { const next = new Set(collapsed.value); next.has(id) ? next.delete(id) : next.add(id); collapsed.value = next; }
function display(value) { return typeof value === 'boolean' ? value ? '是' : '否' : typeof value === 'object' ? JSON.stringify(value, null, 2) : String(value ?? ''); }
watch(() => props.contextKey, () => { ticket++; selected.value = null; loading.value = false; error.value = null; collapsed.value = new Set(); });
</script>
<template>
  <section class="library-structure" aria-label="只读结构预览"><div class="library-structure-tree"><div class="library-structure-title"><strong>JMeter 组件结构</strong><button @click="collapsed = new Set()">全部展开</button></div><p>按父子作用域与同级顺序展示</p><div role="tree" aria-label="JMeter 父子结构" class="library-structure-items"><VirtualList :items="rows" :row-height="36" :item-key="row=>row.node.id" height="100%"><template #default="{item:row}"><div class="library-structure-row" :class="{ selected: node?.id === row.node.id }" :style="{ paddingLeft: `${10 + row.depth * 18}px` }" role="treeitem" :aria-level="row.depth + 1" :aria-expanded="row.hasChildren ? !collapsed.has(row.node.id) : undefined"><button v-if="row.hasChildren" class="library-structure-toggle" :aria-label="`${collapsed.has(row.node.id) ? '展开' : '折叠'} ${nodeName(row.node)}`" @click="toggle(row.node.id)"><Icon :name="collapsed.has(row.node.id) ? 'right' : 'down'" :size="13"/></button><span v-else class="library-structure-spacer"/><button class="library-structure-node" :aria-label="`选择结构组件 ${nodeName(row.node)}`" @click="choose(row.node.id)"><Icon name="file" :size="15"/><span>{{ nodeName(row.node) }}</span><small v-if="isOpaque(row.node)">原样保留</small></button></div></template></VirtualList></div></div>
    <div v-if="loading || lazyNode(node)" class="library-structure-parameters"><p v-if="loading" role="status">正在读取节点参数…</p><template v-else><p role="alert">{{ error?.message || '节点参数尚未加载' }}</p><Button @click="choose(selected)">重试读取节点</Button></template></div><div v-else-if="node" class="library-structure-parameters"><div class="library-structure-heading"><span><Icon name="code" :size="19"/></span><div><h3>{{ nodeName(node) }}</h3><p>{{ info.title }} · {{ node.properties.enabled ? '已启用' : '已停用' }}</p></div><small>只读</small></div><Notice v-if="isOpaque(node)">未知组件及子流程原样保留，不展开插件内部结构。</Notice><p class="library-structure-type"><span>组件类型</span><code>{{ node.properties.component }}</code></p><dl v-if="parameters.length" class="library-parameter-reference"><div v-for="parameter in parameters" :key="parameter.key"><dt>{{ parameter.label }}<code>{{ parameter.key }}</code></dt><dd><pre>{{ display(parameter.value) }}</pre></dd></div></dl><p v-else class="library-structure-empty">此组件没有额外参数。</p><details v-if="node.properties.raw_xml" class="library-structure-raw" :open="rawOpen" @toggle="rawOpen = $event.target.open"><summary>导入原文（只读）</summary><CodePreview v-if="rawOpen" :content="node.properties.raw_xml" label="导入原文（只读）" fragment compact/></details></div><p v-else class="library-structure-parameters">选择一个组件，读取节点参数。</p>
  </section>
</template>
<style scoped>
.library-structure{display:grid;grid-template-columns:minmax(220px,.85fr) minmax(0,1.3fr);grid-template-rows:minmax(0,1fr);height:100%;min-height:0;min-width:0;border:1px solid var(--border);border-radius:10px;background:var(--surface);overflow:hidden}.library-structure-tree{display:flex;flex-direction:column;min-height:0;min-width:0;border-right:1px solid var(--border);padding:18px 0;overflow:hidden}.library-structure-items{flex:1;min-height:0;overflow:hidden}.library-structure-title,.library-structure-tree>p{flex:none}.library-structure-title{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 17px;font-size:12px;color:var(--text)}.library-structure-title>button{font-size:10px;border:0;background:transparent;color:var(--accent);cursor:pointer}.library-structure-tree>p{font-size:10px;color:var(--muted);margin:10px 17px 18px}.library-structure-row{display:flex;align-items:center;gap:3px;padding:4px 10px;min-height:34px;margin:1px 8px;border-radius:6px;color:var(--muted)}.library-structure-row.selected{background:var(--accent-soft);color:var(--accent)}.library-structure-toggle{display:flex;align-items:center;justify-content:center;width:17px;height:22px;border:0;background:transparent;color:inherit;cursor:pointer;flex:none;padding:0}.library-structure-spacer{width:17px;flex:none}.library-structure-node{display:flex;align-items:center;gap:7px;min-width:0;flex:1;text-align:left;color:inherit;border:0;background:transparent;font-size:11px;padding:3px;cursor:pointer;white-space:nowrap}.library-structure-node>svg{flex:none}.library-structure-node>span{overflow:hidden;text-overflow:ellipsis}.library-structure-node>small{font-size:8px;color:var(--muted);flex:none}.library-structure-parameters{padding:23px;overflow:auto;min-height:0;min-width:0;margin:0}.library-structure-heading{display:flex;align-items:center;gap:12px;margin-bottom:20px}.library-structure-heading>span{display:flex;align-items:center;justify-content:center;width:38px;height:38px;border-radius:9px;background:var(--accent-soft);color:var(--accent);flex:none}.library-structure-heading h3{font-size:16px;margin:0;color:var(--text)}.library-structure-heading p{font-size:10px;color:var(--muted);margin:5px 0 0}.library-structure-heading>small{margin-left:auto;color:var(--muted);font-size:10px}.library-structure-type{display:flex;align-items:flex-start;gap:18px;font-size:10px;color:var(--muted);padding:12px 0;border-bottom:1px solid var(--border)}.library-structure-type code{color:var(--text);overflow-wrap:anywhere;font-size:10px}.library-parameter-reference{margin:15px 0}.library-parameter-reference>div{display:grid;grid-template-columns:120px minmax(0,1fr);gap:15px;border-bottom:1px solid var(--border);padding:12px 0;font-size:11px}.library-parameter-reference dt{color:var(--muted);line-height:1.7}.library-parameter-reference dt code{display:block;font-size:9px;margin-top:3px;overflow-wrap:anywhere}.library-parameter-reference dd{margin:0;min-width:0}.library-parameter-reference pre,.library-structure-raw pre{white-space:pre-wrap;overflow-wrap:anywhere;font:10px/1.85 ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--text);margin:0}.library-structure-empty{font-size:11px;color:var(--muted);margin-top:22px}.library-structure-raw{font-size:10px;color:var(--accent);margin-top:22px}.library-structure-raw summary{cursor:pointer}.library-structure-raw pre{margin-top:12px;background:var(--page);padding:13px;border-radius:7px;max-height:260px;overflow:auto}@media(max-width:800px){.library-structure{grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(140px,.8fr) minmax(0,1fr)}.library-structure-tree{border-right:0;border-bottom:1px solid var(--border)}.library-structure-parameters{padding:18px}.library-parameter-reference>div{grid-template-columns:100px minmax(0,1fr);gap:10px}}
</style>
